let video=$('#stageVideo');const screen=$('#filmScreen');let active=0,filter='all',wantPlay=!reduced,hoverPaused=false,visibleWork=false,nearWork=false,previousFocus,switchToken=0,pendingSwitch=null,mediaStarted=false,prefetchTimer=0;const connection=navigator.connection;const constrained=()=>connection?.saveData||/^(slow-)?2g$/.test(connection?.effectiveType||'');let standby=document.createElement('video');standby.id='queuedVideo';standby.className='queued-video';standby.muted=true;standby.defaultMuted=true;standby.playsInline=true;standby.preload='none';standby.setAttribute('aria-hidden','true');screen.append(standby);
