function drawStrip(){const selected=projects.filter(p=>filter==='all'||p.category===filter);$('#filmstrip').innerHTML='<div class="collection-heading"><span>THE COLLECTION</span><small>Choose a project to take a closer look</small></div><div class="project-index">'+selected.map(p=>'<button class="film-card '+(p===projects[active]?'active':'')+'" data-project="'+p.id+'" aria-label="Watch '+p.name+'" aria-pressed="'+(p===projects[active])+'" style="--project-start:'+projectColors[p.id][0]+';--project-end:'+projectColors[p.id][1]+'"><span class="project-swatch" aria-hidden="true"></span><span class="project-number">'+String(projects.indexOf(p)+1).padStart(2,'0')+'</span><span class="project-choice"><strong>'+p.name+'</strong><small>'+p.type+'</small></span><span class="project-arrow" aria-hidden="true">&#8599;</span></button>').join('')+'</div>';}

