function prepare(v,p){const src=film(p);if(v.dataset.source===src)return;v.pause();v.dataset.source=src;v.dataset.project=p.id;v.preload='auto';v.muted=true;v.defaultMuted=true;v.playsInline=true;v.src=src;v.load();}
function nextProject(){const list=projects.filter(p=>filter==='all'||p.category===filter),i=list.findIndex(p=>p.id===projects[active].id);return list[(i+1)%list.length]}
function queueNext(){clearTimeout(prefetchTimer);if(!visibleWork||document.hidden||constrained()||pendingSwitch||!mediaStarted||!wantPlay)return;if(video.currentTime<1.5&&!video.ended){if(!video.paused)prefetchTimer=setTimeout(queueNext,Math.max(100,(1.5-video.currentTime)*1000));return;}const next=nextProject();if(next.id!==projects[active].id)prepare(standby,next)}

function maybePlay(){if(!mediaStarted)return;if(wantPlay&&!hoverPaused&&visibleWork&&!document.hidden&&!document.querySelector('dialog[open]')){if(video.paused)video.play().catch(()=>{})}else if(!video.paused)video.pause();}
function loadProject(){const p=projects[active];screen.classList.toggle('portrait',p.id==='math');$('#stagePoster').src=poster(p);$('#stagePoster').alt=p.name+' film';showDetails();if(nearWork&&!mediaStarted){mediaStarted=true;prepare(video,p)}}
function selectProject(id,opts={}){const next=projects.findIndex(p=>p.id===id);if(next<0)return;if(opts.play!==undefined)wantPlay=opts.play;if(opts.scroll)$('.cinema-layout').scrollIntoView({behavior:reduced?'instant':'smooth',block:'nearest'});if(next===active){if(pendingSwitch)pendingSwitch();pendingSwitch=null;switchToken++;loadProject();maybePlay();queueNext();return;}const token=++switchToken;if(pendingSwitch)pendingSwitch();let timer;const candidate=standby;const cleanup=()=>{clearTimeout(timer);candidate.removeEventListener('loadeddata',commit);candidate.removeEventListener('error',failed)};const failed=()=>{cleanup();if(token!==switchToken)return;pendingSwitch=null;$('#filmLabel').textContent='Film could not load. Choose a project to retry.';};const commit=()=>{if(token!==switchToken||candidate.readyState<2||candidate.dataset.project!==id)return;cleanup();pendingSwitch=null;const old=video;old.pause();old.removeAttribute('id');old.classList.add('queued-video');old.setAttribute('aria-hidden','true');video=candidate;video.id='stageVideo';video.classList.remove('queued-video');video.removeAttribute('aria-hidden');standby=old;standby.id="queuedVideo";active=next;screen.classList.add('ready');screen.classList.toggle('portrait',id==='math');$('#stagePoster').src=poster(projects[active]);$('#stagePoster').alt=projects[active].name+' film';showDetails();maybePlay();queueNext();};pendingSwitch=cleanup;candidate.addEventListener('loadeddata',commit);candidate.addEventListener('error',failed);timer=setTimeout(failed,20000);prepare(candidate,projects[next]);if(candidate.readyState>=2)commit();}
function bindMedia(v){v.addEventListener('playing',()=>{if(v===video)queueNext()});v.addEventListener('loadeddata',()=>{if(v!==video)return;screen.classList.add('ready');maybePlay();queueNext()});v.addEventListener('play',()=>{if(v===video)screen.classList.add('playing')});v.addEventListener('pause',()=>{if(v===video)screen.classList.remove('playing')});v.addEventListener('ended',()=>{if(v===video)selectProject(nextProject().id,{play:true})});v.addEventListener('error',()=>{if(v===video)$('#filmLabel').textContent='Film could not load. Choose a project to retry.'})}bindMedia(video);bindMedia(standby);
screen.addEventListener('pointerenter',e=>{if(e.pointerType==='touch')return;hoverPaused=true;maybePlay()});screen.addEventListener('pointerleave',()=>{hoverPaused=false;maybePlay()});screen.addEventListener('click',e=>{if(e.target.tagName!=='VIDEO')return;if(matchMedia('(hover:none)').matches){wantPlay=video.paused;maybePlay()}});
