function setHeroMode(m){stopHero();heroMode=m;heroIndex=0;heroElapsed=0;$$('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===m));renderHero();startHero();}

function stopHero(){$('#heroDemo').dataset.motion='paused';cancelAnimationFrame(heroRAF);heroRAF=0;heroLast=0;$('#heroFilm')?.pause()}
function startHero(){if(heroPaused||!heroVisible||document.hidden||document.querySelector('dialog[open]'))return;$('#heroDemo').dataset.motion='running';const v=$('#heroFilm');if(v&&!v.getAttribute('src'))v.src=v.dataset.source;if(v&&v.paused)v.play().catch(()=>{});if(!heroRAF)heroRAF=requestAnimationFrame(heroTick)}
function heroTick(t){heroRAF=0;if(heroPaused||!heroVisible||document.hidden||document.querySelector('dialog[open]')){stopHero();return;}const v=$('#heroFilm');if(t-heroUIAt>=100){heroUIAt=t;if(v){$('#heroProgress').style.transform='scaleX('+Math.min(1,v.currentTime/(v.duration||16.5))+')';const ix=[3,7,10.5,13,16.6].findIndex(end=>v.currentTime<end);$('#heroCounter').textContent=String((ix<0?4:ix)+1).padStart(2,'0')+' / 05';}else{const done=stepDurations.slice(0,heroIndex).reduce((a,b)=>a+b,0)+heroElapsed;$('#heroProgress').style.transform='scaleX('+(done/16500)+')'}}if(!v){if(heroLast)heroElapsed+=Math.min(t-heroLast,100);if(heroElapsed>=stepDurations[heroIndex]){heroElapsed=0;heroIndex=(heroIndex+1)%5;renderHero()}}heroLast=t;heroRAF=requestAnimationFrame(heroTick)}
