let flowMode='voice',flowStep=0;const flows={voice:[['agent','Thanks for calling. How can I help?'],['visitor','I’d like an appointment tomorrow afternoon.'],['agent','I can help with the request. What’s your name and contact number?'],['visitor','Alex. These are my sample contact details.'],['agent','Thank you. Your request is ready for the team to follow up.']],chat:[['visitor','Can you help me choose a service?'],['agent','Of course. What would you like help with?'],['visitor','I’d like to arrange a consultation.'],['agent','Let’s collect your name and contact details so the team can help.'],['visitor','Alex. These are my sample contact details.']]};
function renderFlow(){$$('[data-flow]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.flow===flowMode));$('#flowContent').innerHTML=flows[flowMode].slice(0,flowStep+1).map(([role,text])=>'<div class="flow-line '+role+'"><small>'+((role==='agent')?(flowMode==='voice'?'Voice agent':'Chatbot'):'Example customer')+'</small>'+text+'</div>').join('')+(flowStep===4?'<div class="flow-success">Example enquiry captured.<br>No real call, message or booking was created.</div>':'');$('#flowNext').textContent=flowStep===4?'Talk about your own flow ↗':'Next step ↗';}
