$('#flowNext').addEventListener('click',()=>{if(flowStep<4){flowStep++;renderFlow()}else{dialogClose('#demoDialog');openContact();}});
$('#flowReset').addEventListener('click',()=>{flowStep=0;renderFlow()});
function openContact(p){const form=$('#contactForm');if(p){form.elements.service.value='A system inspired by this project';form.elements.message.value='I’m interested in a system inspired by '+p.name+'. Here is what I need: ';}dialogOpen('#contactDialog');}
$('#contactForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const status=$('#contactStatus'),button=f.querySelector('[type=submit]');status.textContent='';if(location.protocol==='file:'){status.textContent='Online submission is available on the hosted website. You can email connect@alacritydesigns.com directly.';return;}button.disabled=true;button.textContent='Sending…';const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const payload=Object.fromEntries(new FormData(f));payload._subject='Alacrity enquiry — '+payload.service;payload._template='table';payload._url=location.href;const response=await fetch('https://formsubmit.co/ajax/connect@alacritydesigns.com',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload),signal:controller.signal});const data=await response.json();if(!response.ok||!(data.success===true||data.success==='true'))throw new Error('submission');status.textContent='Thank you. Your enquiry has been submitted.';f.reset();}catch{status.textContent='Your enquiry could not be confirmed. Please try again or email connect@alacritydesigns.com. Your details are still here.';}finally{clearTimeout(timeout);button.disabled=false;button.textContent='Send enquiry';}});

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.project){selectProject(b.dataset.project,{play:true,scroll:true});return}if(b.dataset.filter){filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});if(pendingSwitch){pendingSwitch();pendingSwitch=null;switchToken++}if(filter!=='all'&&projects[active].category!==filter){selectProject(projects.find(p=>p.category===filter).id,{play:!reduced})}drawStrip();queueNext();return}if(b.dataset.next){const list=projects.filter(p=>filter==='all'||p.category===filter),pos=list.findIndex(p=>p===projects[active]);selectProject(list[(pos+Number(b.dataset.next)+list.length)%list.length].id,{play:true});return}if(b.dataset.mode){setHeroMode(b.dataset.mode);return}if(b.dataset.flow){flowMode=b.dataset.flow;flowStep=0;renderFlow();return}if(b.hasAttribute('data-demo')){openFlow();return}if(b.dataset.service){openFlow(b.dataset.service);return}if(b.dataset.enquire){openContact(projects.find(p=>p.id===b.dataset.enquire));return}if(b.hasAttribute('data-contact')){openContact();return}if(b.dataset.close){dialogClose('#'+b.dataset.close);return}if(b.id==='themeToggle')setTheme(document.documentElement.dataset.theme!=='dark');});
$$('dialog').forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();dialogClose('#'+d.id)});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialogClose('#'+d.id)});});
